style.css:
@-moz-document url-prefix("https://www.roblox.com") {
/* Follower-Zahl manipulieren */
  .profile-followers .text-label::after {
    content: "586,000 Followers ?";
    font-weight: bold;
    color: #ff69b4;
    font-size: 16px;
    margin-left: 10px;
  }

  /* Optional: Original Zahl ausblenden */
  .profile-followers .text-label span {
    display: none !important;
  }
}
